import React, { useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { AppProvider, useApp } from './context';
import { Layout } from './components/Layout';
import { Welcome, BuyerDashboard } from './pages/Home';
import { SearchPage } from './pages/Search';
import { ProductDetail, Cart, Checkout, StorePage } from './pages/Product';
import { VendorDashboard, VendorProducts, AddProduct, EditProduct, VendorOrders, VendorOnboarding } from './pages/Vendor';
import { AdminDashboard } from './pages/Admin';
import { UserProfile, OrdersPage, WishlistPage } from './pages/Profile';
import { Login, Register, AdminLogin, ForgotPassword, UpdatePassword } from './pages/Auth';
import { DeliveryDashboard } from './pages/Delivery';
import { AboutPage } from './pages/About';
import { supabase } from './supabaseClient';

const ProtectedRoute: React.FC<{ children: React.ReactNode; role?: string }> = ({ children, role }) => {
    const { currentUser, currentRole, isLoading } = useApp();

    if (isLoading) return <div className="min-h-screen flex items-center justify-center"><div className="animate-spin rounded-full h-8 w-8 border-2 border-primary border-b-transparent"></div></div>;

    if (!currentUser) return <Navigate to="/login" />;
    if (role && currentRole !== role && currentRole !== 'admin') return <Navigate to="/" />; 
    return <>{children}</>;
};

// Component to handle global auth events like password recovery
const AuthEventHandler = () => {
    const navigate = useNavigate();

    useEffect(() => {
        const { data: authListener } = supabase.auth.onAuthStateChange((event, session) => {
            if (event === 'PASSWORD_RECOVERY') {
                navigate('/update-password');
            }
        });
        return () => {
            authListener.subscription.unsubscribe();
        };
    }, [navigate]);

    return null;
}

const AppContent = () => {
  return (
    <Layout>
      <AuthEventHandler />
      <Routes>
        {/* Public / Entry */}
        <Route path="/" element={<Welcome />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/update-password" element={<UpdatePassword />} />

        {/* Public Store Page */}
        <Route path="/store/:vendorId" element={<StorePage />} />
        <Route path="/about" element={<AboutPage />} />

        {/* Secret Admin Route */}
        <Route path="/secret-access" element={<AdminLogin />} />

        {/* Buyer Routes */}
        <Route path="/buyer/dashboard" element={<BuyerDashboard />} />
        <Route path="/buyer/search" element={<SearchPage />} />
        <Route path="/buyer/product/:id" element={<ProductDetail />} />
        <Route path="/buyer/cart" element={<Cart />} />
        <Route path="/buyer/checkout" element={<Checkout />} />
        <Route path="/buyer/orders" element={<ProtectedRoute role="buyer"><OrdersPage /></ProtectedRoute>} />
        <Route path="/buyer/wishlist" element={<ProtectedRoute role="buyer"><WishlistPage /></ProtectedRoute>} />
        <Route path="/buyer/profile" element={<ProtectedRoute><UserProfile /></ProtectedRoute>} />

        {/* Vendor Routes */}
        <Route path="/vendor/onboarding" element={<ProtectedRoute><VendorOnboarding /></ProtectedRoute>} />
        <Route path="/vendor/dashboard" element={<ProtectedRoute role="vendor"><VendorDashboard /></ProtectedRoute>} />
        <Route path="/vendor/products" element={<ProtectedRoute role="vendor"><VendorProducts /></ProtectedRoute>} />
        <Route path="/vendor/products/new" element={<ProtectedRoute role="vendor"><AddProduct /></ProtectedRoute>} />
        <Route path="/vendor/products/:id/edit" element={<ProtectedRoute role="vendor"><EditProduct /></ProtectedRoute>} />
        <Route path="/vendor/orders" element={<ProtectedRoute role="vendor"><VendorOrders /></ProtectedRoute>} />
        <Route path="/vendor/profile" element={<ProtectedRoute role="vendor"><UserProfile /></ProtectedRoute>} />

        {/* Delivery Routes */}
        <Route path="/delivery/dashboard" element={<ProtectedRoute role="courier"><DeliveryDashboard /></ProtectedRoute>} />

        {/* Admin Routes */}
        <Route path="/admin/dashboard" element={<ProtectedRoute role="admin"><AdminDashboard /></ProtectedRoute>} />
      </Routes>
    </Layout>
  );
}

const App: React.FC = () => {
  return (
    <AppProvider>
      <Router>
         <AppContent />
      </Router>
    </AppProvider>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { useApp } from '../context';
import { Button, Card, Input, Badge, Avatar, Spinner } from '../components/UI';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabaseClient';
import { Role, TransportType } from '../types';

// --- Order Progress Tracker ---
const OrderProgress: React.FC<{ order: any }> = ({ order }) => {
    const steps = order.deliveryOption === 'delivery' 
        ? ['placed', 'received', 'preparing', 'courier_assigned', 'delivering', 'delivered']
        : ['placed', 'received', 'preparing', 'ready_for_pickup', 'delivered'];

    const currentIndex = steps.indexOf(order.status);

    return (
        <div className="py-4">
            <div className="flex justify-between relative">
                <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-gray-100 dark:bg-gray-800 -translate-y-1/2 z-0"></div>
                <div 
                    className="absolute top-1/2 left-0 h-0.5 bg-primary -translate-y-1/2 z-0 transition-all duration-500"
                    style={{ width: `${(currentIndex / (steps.length - 1)) * 100}%` }}
                ></div>
                {steps.map((step, idx) => (
                    <div key={step} className="relative z-10 flex flex-col items-center">
                        <div className={`w-3 h-3 rounded-full border-2 transition-colors duration-300 ${idx <= currentIndex ? 'bg-primary border-primary' : 'bg-white dark:bg-darkSurface border-gray-200 dark:border-gray-700'}`}></div>
                    </div>
                ))}
            </div>
            <div className="flex justify-between mt-2">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Start</span>
                <span className="text-[10px] font-bold text-primary uppercase tracking-tighter">{order.status.replace('_', ' ')}</span>
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">Done</span>
            </div>
        </div>
    );
};

// --- Profile Header ---
const ProfileHeader: React.FC = () => {
    const { currentUser, updateProfile, uploadFile } = useApp();
    const [editing, setEditing] = useState(false);
    const [name, setName] = useState(currentUser?.name || '');
    const [address, setAddress] = useState(currentUser?.address || '');
    const [uploading, setUploading] = useState(false);
    const fileRef = useRef<HTMLInputElement>(null);

    const handleAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if(e.target.files?.[0]) {
            setUploading(true);
            const url = await uploadFile(e.target.files[0], 'avatars');
            if(url) await updateProfile({ avatarUrl: url });
            setUploading(false);
        }
    };

    const handleSave = async () => {
        await updateProfile({ name, address });
        setEditing(false);
    };

    return (
        <div className="bg-white dark:bg-darkSurface p-6 rounded-b-[2.5rem] shadow-sm text-center relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-24 bg-gradient-to-br from-primary/5 to-secondary/5 -z-10"></div>
            <div className="flex justify-center mb-4 relative">
                <div className="relative group">
                    <Avatar src={currentUser?.avatarUrl} name={currentUser?.name || ''} size="2xl" className="border-4 border-white dark:border-darkBg shadow-lg" />
                    <button 
                        onClick={() => fileRef.current?.click()}
                        className="absolute bottom-0 right-0 w-8 h-8 bg-gray-900 text-white rounded-full flex items-center justify-center shadow-lg hover:bg-primary transition-colors"
                    >
                        <i className={`fa-solid ${uploading ? 'fa-spinner fa-spin' : 'fa-camera'} text-xs`}></i>
                    </button>
                </div>
                <input type="file" ref={fileRef} hidden onChange={handleAvatar} />
            </div>

            {editing ? (
                <div className="space-y-3 max-w-xs mx-auto animate-fade-in">
                    <Input value={name} onChange={e => setName(e.target.value)} placeholder="Full Name" className="text-center" />
                    <Input value={address} onChange={e => setAddress(e.target.value)} placeholder="Campus Location" className="text-center" />
                    <div className="flex gap-2">
                        <Button fullWidth size="sm" onClick={handleSave}>Save</Button>
                        <Button variant="secondary" fullWidth size="sm" onClick={() => setEditing(false)}>Cancel</Button>
                    </div>
                </div>
            ) : (
                <div className="animate-fade-in">
                    <h1 className="text-2xl font-display font-black text-gray-900 dark:text-white">{currentUser?.name}</h1>
                    <p className="text-gray-400 dark:text-gray-500 text-sm font-medium mb-1">{currentUser?.email}</p>
                    <p className="text-xs text-primary font-bold flex items-center justify-center gap-1">
                        <i className="fa-solid fa-location-dot"></i> {currentUser?.address || 'Set Location'}
                    </p>
                    <button onClick={() => setEditing(true)} className="mt-4 text-xs font-bold text-gray-400 dark:text-gray-500 bg-gray-50 dark:bg-gray-800 px-4 py-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors">
                        Edit Profile
                    </button>
                </div>
            )}
        </div>
    );
};

// --- Settings Section ---
