                icon="palette" 
                label="Appearance" 
                onClick={() => setShowThemeModal(true)} 
                rightContent={<span className="text-[10px] font-bold text-primary uppercase">{theme}</span>}
            />
            <ActionItem icon="shield-halved" label="Security & Password" onClick={() => navigate('/update-password')} />
            <ActionItem icon="bell" label="Notifications" onClick={() => {}} />
            <ActionItem icon="right-from-bracket" label="Sign Out" danger onClick={async () => { await logout(); navigate('/'); }} />

            {showThemeModal && (
                <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
