                        <div className="flex justify-between items-center mb-6">
                            <div>
                                <h3 className="text-xl font-bold dark:text-white">Appearance</h3>
                                <p className="text-xs text-gray-400">Choose your preferred theme</p>
                            </div>
                            <button onClick={() => setShowThemeModal(false)} className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center">
                                <i className="fa-solid fa-xmark text-gray-400"></i>
                            </button>
                        </div>
                        <div className="space-y-3">
                            {[
                                { id: 'light', label: 'Light Mode', icon: 'sun', desc: 'Classic bright look' },
                                { id: 'dark', label: 'Dark Mode', icon: 'moon', desc: 'Easy on the eyes at night' },
                                { id: 'system', label: 'System Default', icon: 'circle-half-stroke', desc: 'Syncs with your device' }
                            ].map((mode) => (
                                <div 
                                    key={mode.id}
                                    onClick={() => { updateTheme(mode.id as any); setShowThemeModal(false); }}
                                    className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all cursor-pointer ${theme === mode.id ? 'border-primary bg-primary/5 text-primary' : 'border-gray-50 dark:border-gray-800 text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800'}`}
                                >
                                    <div className="flex items-center gap-4">
                                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${theme === mode.id ? 'bg-primary/10' : 'bg-gray-100 dark:bg-gray-700'}`}>
                                            <i className={`fa-solid fa-${mode.icon}`}></i>
                                        </div>
                                        <div className="text-left">
                                            <p className="font-bold text-sm">{mode.label}</p>
                                            <p className="text-[10px] opacity-70">{mode.desc}</p>
                                        </div>
                                    </div>
                                    {theme === mode.id && <i className="fa-solid fa-circle-check"></i>}
