};

// --- App Info ---
const AppInfoSection: React.FC = () => {
    const { submitContactMessage } = useApp();
    const navigate = useNavigate();
    const [showContact, setShowContact] = useState(false);
    const [contactForm, setContactForm] = useState({ name: '', email: '', message: '' });

    const handleContact = async (e: React.FormEvent) => {
        e.preventDefault();
        await submitContactMessage(contactForm.name, contactForm.email, contactForm.message);
        setShowContact(false);
        setContactForm({ name: '', email: '', message: '' });
    };

    return (
        <div className="px-4 mt-8 pb-12">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-3">App Info</h3>
            <div className="grid grid-cols-2 gap-3">
                <button onClick={() => navigate('/about')} className="p-3 bg-white dark:bg-darkSurface rounded-xl text-left border border-gray-50 dark:border-transparent shadow-sm active:scale-95 transition-all">
                    <p className="text-xs font-bold text-gray-600 dark:text-gray-300">About Us</p>
                </button>
                {['FAQ', 'Terms', 'Privacy'].map(item => (
                    <button key={item} className="p-3 bg-white dark:bg-darkSurface rounded-xl text-left border border-gray-50 dark:border-transparent shadow-sm active:scale-95 transition-all">
                        <p className="text-xs font-bold text-gray-600 dark:text-gray-300">{item}</p>
                    </button>
                ))}
            </div>
            <button 
                onClick={() => setShowContact(true)}
                className="w-full mt-3 p-4 bg-gradient-to-r from-gray-900 to-gray-800 text-white rounded-2xl font-bold text-sm shadow-lg active:scale-95 transition-all"
            >
                Contact Support
            </button>

            {showContact && (
                <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
                    <Card className="p-6 w-full max-w-sm animate-slide-up bg-white dark:bg-darkSurface">
                        <h3 className="text-xl font-bold mb-4 dark:text-white">Contact Us</h3>
                        <form onSubmit={handleContact} className="space-y-4">
                            <Input label="Name" value={contactForm.name} onChange={e => setContactForm({...contactForm, name: e.target.value})} required />
                            <Input label="Email" type="email" value={contactForm.email} onChange={e => setContactForm({...contactForm, email: e.target.value})} required />
                            <textarea 
                                className="w-full h-32 p-4 bg-gray-50 dark:bg-gray-800 dark:text-white rounded-2xl text-sm border-transparent focus:ring-primary focus:ring-2"
                                placeholder="How can we help?"
                                value={contactForm.message}
                                onChange={e => setContactForm({...contactForm, message: e.target.value})}
                                required
                            />
                            <div className="flex gap-2">
                                <Button fullWidth type="submit">Send</Button>
                                <Button variant="secondary" fullWidth type="button" onClick={() => setShowContact(false)}>Cancel</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

// --- Role Toggles ---
const RoleSwitcher: React.FC = () => {
    const { currentUser, currentRole, switchRole, registerCourier, couriers } = useApp();
    const navigate = useNavigate();
    const [showCourierReg, setShowCourierReg] = useState(false);
    const [regForm, setRegForm] = useState({ fullName: '', vehicleType: 'Motorbike', transportType: 'Motorbike' as TransportType, payoutMethod: 'MoMo', deliveryRadius: 5 });

    const deliveryProfile = couriers.find(d => d.userId === currentUser?.id);
    const isCourier = currentUser?.roles.includes('courier');
    const isVendor = currentUser?.roles.includes('vendor');

    const handleCourierReg = async (e: React.FormEvent) => {
        e.preventDefault();
        await registerCourier(regForm);
        setShowCourierReg(false);
    };

    return (
        <div className="px-4 mt-6">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-3">Your Roles</h3>
            <div className="flex gap-2 mb-4 overflow-x-auto pb-2 hide-scrollbar">
                <button 
                    onClick={() => { switchRole('buyer'); navigate('/buyer/dashboard'); }}
                    className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'buyer' ? 'bg-primary text-white border-primary shadow-lg shadow-primary/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
                >
                    <i className="fa-solid fa-bag-shopping block mb-1"></i> Buyer
                </button>
                {isVendor && (
                    <button 
                        onClick={() => { switchRole('vendor'); navigate('/vendor/dashboard'); }}
                        className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'vendor' ? 'bg-secondary text-white border-secondary shadow-lg shadow-secondary/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
                    >
                        <i className="fa-solid fa-store block mb-1"></i> Vendor
                    </button>
                )}
                {isCourier && deliveryProfile?.status === 'approved' && (
                    <button 
                        onClick={() => { switchRole('courier'); navigate('/delivery/dashboard'); }}
                        className={`flex-1 min-w-[100px] p-3 rounded-2xl font-bold text-xs transition-all border ${currentRole === 'courier' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-600/20' : 'bg-white dark:bg-darkSurface text-gray-400 dark:text-gray-500 border-gray-100 dark:border-gray-800'}`}
                    >
                        <i className="fa-solid fa-motorcycle block mb-1"></i> Delivery
                    </button>
                )}
            </div>

            {!isCourier && !deliveryProfile && (
                <Card className="p-4 bg-gradient-to-br from-blue-600 to-blue-800 text-white border-none shadow-blue-200">
                    <h4 className="font-bold text-sm mb-1">Earn as you walk</h4>
                    <p className="text-[10px] opacity-80 mb-3">Deliver orders across campus and earn ₵10+ per trip.</p>
                    <Button variant="secondary" size="sm" onClick={() => setShowCourierReg(true)}>Register as Courier</Button>
                </Card>
            )}

            {deliveryProfile?.status === 'pending' && (
                <div className="bg-yellow-50 dark:bg-yellow-900/10 border border-yellow-100 dark:border-yellow-900/20 p-4 rounded-2xl flex items-center gap-3">
                    <i className="fa-solid fa-clock text-yellow-500"></i>
                    <p className="text-xs font-bold text-yellow-700 dark:text-yellow-500">Courier application is under review.</p>
                </div>
            )}

            {!isVendor && (
                <Card className="p-4 mt-3 bg-gradient-to-br from-pink-500 to-rose-600 text-white border-none shadow-pink-200">
                    <h4 className="font-bold text-sm mb-1">Sell on LYNQED</h4>
                    <p className="text-[10px] opacity-80 mb-3">Launch your business and reach campus customers instantly.</p>
                    <Button variant="secondary" size="sm" onClick={() => navigate('/vendor/onboarding')}>Open Your Store</Button>
                </Card>
            )}

            {showCourierReg && (
                <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
                    <Card className="p-6 w-full max-w-md rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface">
                        <h3 className="text-xl font-bold mb-1 dark:text-white">Courier Registration</h3>
                        <p className="text-xs text-gray-400 mb-6">Join our logistics fleet</p>
                        <form onSubmit={handleCourierReg} className="space-y-4">
                            <Input label="Full Name" value={regForm.fullName} onChange={e => setRegForm({...regForm, fullName: e.target.value})} required />
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Transport Type</label>
                                <div className="grid grid-cols-2 gap-2">
                                    {['Walking', 'Bicycle', 'Motorbike', 'Other'].map(type => (
                                        <div 
                                            key={type}
                                            onClick={() => setRegForm({...regForm, transportType: type as any})}
                                            className={`p-3 rounded-xl border-2 text-center text-xs font-bold transition-all cursor-pointer ${regForm.transportType === type ? 'border-primary bg-primary/5 text-primary' : 'border-gray-50 dark:border-gray-800 text-gray-400'}`}
                                        >
                                            {type}
                                        </div>
                                    ))}
                                </div>
                            </div>
                            <Input label="Preferred Payout Method" value={regForm.payoutMethod} onChange={e => setRegForm({...regForm, payoutMethod: e.target.value})} required />
                            <div className="flex gap-2 pt-4">
                                <Button fullWidth type="submit">Apply Now</Button>
                                <Button variant="secondary" fullWidth type="button" onClick={() => setShowCourierReg(false)}>Close</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}
        </div>
    );
};

// --- Role Specific Contents ---
const BuyerContent: React.FC = () => {
    const { orders, currentUser, favorites, products } = useApp();
    const navigate = useNavigate();
    const myOrders = orders.filter(o => o.buyerId === currentUser?.id).sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    const myWishlist = products.filter(p => favorites.includes(p.id));

    return (
        <div className="animate-fade-in">
            <div className="px-4 mt-6">
                <div className="flex justify-between items-center mb-3">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Your Orders</h3>
                    <button className="text-[10px] font-bold text-primary" onClick={() => navigate('/buyer/orders')}>View History</button>
                </div>
                <div className="space-y-3">
                    {myOrders.slice(0, 2).map(order => (
                        <Card key={order.id} className="p-4 bg-white dark:bg-darkSurface" onClick={() => navigate('/buyer/orders')}>
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-xs font-bold text-gray-900 dark:text-white">Order #{order.id.slice(-4)}</span>
                                <Badge color={order.status === 'delivered' ? 'green' : 'blue'}>{order.status.replace('_', ' ')}</Badge>
                            </div>
                            <OrderProgress order={order} />
                            <p className="text-[10px] text-gray-400 font-bold mt-1 uppercase tracking-tight">Total: ₵{order.total.toFixed(2)}</p>
                        </Card>
                    ))}
                    {myOrders.length === 0 && <p className="text-center text-xs text-gray-400 py-6">No recent orders.</p>}
                </div>
            </div>

            <div className="px-4 mt-6">
                <div className="flex justify-between items-center mb-3">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Wishlist</h3>
                    <button className="text-[10px] font-bold text-primary" onClick={() => navigate('/buyer/wishlist')}>Manage</button>
