        <div className="space-y-3 px-4 mt-6">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-2">Account Management</h3>
            <ActionItem 
                icon="palette" 
                label="Appearance" 
                onClick={() => setShowThemeModal(true)} 
                rightContent={<span className="text-[10px] font-bold text-primary uppercase">{theme}</span>}
            />
            <ActionItem icon="shield-halved" label="Security & Password" onClick={() => navigate('/update-password')} />
            <ActionItem icon="bell" label="Notifications" onClick={() => {}} />
            <ActionItem icon="right-from-bracket" label="Sign Out" danger onClick={async () => { await logout(); navigate('/'); }} />

            {showThemeModal && (
                <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-6 animate-fade-in">
                    <Card className="p-6 w-full max-w-md rounded-t-[2.5rem] sm:rounded-3xl animate-slide-up bg-white dark:bg-darkSurface">
                        <div className="flex justify-between items-center mb-6">
                            <div>
                                <h3 className="text-xl font-bold dark:text-white">Appearance</h3>
                                <p className="text-xs text-gray-400">Choose your preferred theme</p>
                            </div>
                            <button onClick={() => setShowThemeModal(false)} className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center">
                                <i className="fa-solid fa-xmark text-gray-400"></i>
                            </button>
                        </div>
                        <div className="space-y-3">
                            {[
                                { id: 'light', label: 'Light Mode', icon: 'sun', desc: 'Classic bright look' },
                                { id: 'dark', label: 'Dark Mode', icon: 'moon', desc: 'Easy on the eyes at night' },
                                { id: 'system', label: 'System Default', icon: 'circle-half-stroke', desc: 'Syncs with your device' }
                            ].map((mode) => (
                                <div 
                                    key={mode.id}
                                    onClick={() => { updateTheme(mode.id as any); setShowThemeModal(false); }}
                                    className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all cursor-pointer ${theme === mode.id ? 'border-primary bg-primary/5 text-primary' : 'border-gray-50 dark:border-gray-800 text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800'}`}
