                    <p className="text-xs font-bold text-gray-600 dark:text-gray-300 group-hover:text-primary transition-colors">About Us</p>
                </button>
                <button onClick={() => {}} className="p-3 bg-white dark:bg-darkSurface rounded-xl text-left border border-gray-100 dark:border-transparent shadow-sm active:scale-95 transition-all">
                    <p className="text-xs font-bold text-gray-600 dark:text-gray-300">FAQ</p>
                </button>
                <button onClick={() => navigate('/terms')} className="p-3 bg-white dark:bg-darkSurface rounded-xl text-left border border-gray-100 dark:border-transparent shadow-sm active:scale-95 transition-all hover:bg-primary/5 hover:border-primary/20 group">
                    <p className="text-xs font-bold text-gray-600 dark:text-gray-300 group-hover:text-primary transition-colors">Terms</p>
                </button>
                <button onClick={() => navigate('/privacy')} className="p-3 bg-white dark:bg-darkSurface rounded-xl text-left border border-gray-100 dark:border-transparent shadow-sm active:scale-95 transition-all hover:bg-primary/5 hover:border-primary/20 group">
                    <p className="text-xs font-bold text-gray-600 dark:text-gray-300 group-hover:text-primary transition-colors">Privacy</p>
