                    myOrders.map(order => (
                        <Card key={order.id} className="p-4 border-gray-100 dark:border-gray-800 shadow-sm">
                            <div className="flex justify-between items-start mb-2">
                                <div>
                                    <span className="font-bold text-gray-900 dark:text-white">Order #{order.id.slice(-4)}</span>
                                    <p className="text-xs text-gray-400 mt-1">{new Date(order.createdAt).toLocaleDateString()}</p>
                                </div>
                                <Badge color="blue">{order.status.replace('_', ' ')}</Badge>
