                                <span className="text-sm text-gray-500 dark:text-gray-400 font-medium">{order.items.length} items</span>
                                <span className="font-bold text-gray-900 dark:text-white">₵{order.total.toFixed(2)}</span>
                            </div>
                        </Card>
                    ))
