export const WishlistPage: React.FC = () => {
    const { favorites, products, toggleFavorite, addToCart, cart, removeFromCart } = useApp();
    const navigate = useNavigate();
    const myWishlist = products.filter(p => favorites.includes(p.id));

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            <div className="bg-white dark:bg-darkSurface p-4 shadow-sm sticky top-0 z-30 flex items-center gap-3 border-b border-gray-100 dark:border-gray-800">
                <button onClick={() => navigate(-1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 dark:text-white transition-colors">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <h1 className="text-xl font-bold font-display dark:text-white">My Wishlist</h1>
            </div>
            <div className="p-4 grid grid-cols-2 gap-3">
                {myWishlist.length === 0 ? (
                    <div className="col-span-2 text-center py-20 text-gray-400">
                        <i className="fa-solid fa-heart text-4xl mb-4 opacity-20"></i>
                        <p className="font-medium">Your wishlist is empty.</p>
                        <Button className="mt-4" onClick={() => navigate('/buyer/dashboard')}>Explore Products</Button>
                    </div>
                ) : (
                    myWishlist.map(product => {
                        const isInCart = cart.some(item => item.productId === product.id);
                        return (
                            <div 
                                key={product.id} 
                                className="bg-white dark:bg-darkSurface rounded-2xl overflow-hidden shadow-card border border-gray-100 dark:border-gray-800 flex flex-col h-full cursor-pointer group"
                                onClick={() => navigate(`/buyer/product/${product.id}`)}
                            >
                                <div className="aspect-square w-full relative overflow-hidden bg-white dark:bg-gray-900">
                                    <img src={product.images[0]} alt={product.title} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-500" />
                                    <button 
                                        className="absolute top-2 right-2 z-10 w-7 h-7 rounded-full bg-white/80 dark:bg-darkBg/80 backdrop-blur-sm border border-gray-100 dark:border-gray-800 text-red-500 flex items-center justify-center transition-colors shadow-sm active:scale-90"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            toggleFavorite(product.id);
                                        }}
                                    >
                                        <i className="fa-solid fa-heart text-xs"></i>
                                    </button>
                                </div>
                                <div className="p-3 flex flex-col justify-between flex-grow bg-white dark:bg-darkSurface">
                                    <div>
                                        <h3 className="text-xs text-gray-800 dark:text-white font-bold leading-tight line-clamp-2 mb-1">{product.title}</h3>
                                    </div>
                                    <div className="flex items-center justify-between mt-2">
                                        <span className="text-sm font-extrabold text-gray-900 dark:text-white">₵{product.price.toFixed(2)}</span>
                                        <button 
                                            className={`w-8 h-8 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 ${isInCart ? 'bg-green-500' : 'bg-black dark:bg-white dark:text-black'}`}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                isInCart ? removeFromCart(product.id) : addToCart(product);
                                            }}
                                        >
                                            <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-xs`}></i>
                                        </button>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
};

import React, { useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { AppProvider, useApp } from './context';
import { Layout } from './components/Layout';
import { Welcome, BuyerDashboard } from './pages/Home';
import { SearchPage } from './pages/Search';
import { ProductDetail, Cart, Checkout, StorePage } from './pages/Product';
import { VendorDashboard, VendorProducts, AddProduct, EditProduct, VendorOrders, VendorOnboarding } from './pages/Vendor';
import { AdminDashboard } from './pages/Admin';
import { UserProfile, OrdersPage, WishlistPage } from './pages/Profile';
import { Login, Register, AdminLogin, ForgotPassword, UpdatePassword } from './pages/Auth';
import { DeliveryDashboard } from './pages/Delivery';
import { AboutPage } from './pages/About';
import { PrivacyPage } from './pages/Privacy';
import { TermsPage } from './pages/Terms';
import { supabase } from './supabaseClient';

const ProtectedRoute: React.FC<{ children: React.ReactNode; role?: string }> = ({ children, role }) => {
    const { currentUser, currentRole, isLoading } = useApp();

    if (isLoading) return <div className="min-h-screen flex items-center justify-center"><div className="animate-spin rounded-full h-8 w-8 border-2 border-primary border-b-transparent"></div></div>;

    if (!currentUser) return <Navigate to="/login" />;
    if (role && currentRole !== role && currentRole !== 'admin') return <Navigate to="/" />; 
    return <>{children}</>;
};

// Component to handle global auth events like password recovery
const AuthEventHandler = () => {
    const navigate = useNavigate();

    useEffect(() => {
        const { data: authListener } = supabase.auth.onAuthStateChange((event, session) => {
            if (event === 'PASSWORD_RECOVERY') {
                navigate('/update-password');
            }
        });
        return () => {
            authListener.subscription.unsubscribe();
        };
    }, [navigate]);

    return null;
}

const AppContent = () => {
  return (
    <Layout>
      <AuthEventHandler />
      <Routes>
        {/* Public / Entry */}
        <Route path="/" element={<Welcome />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/update-password" element={<UpdatePassword />} />

        {/* Public Information Pages */}
        <Route path="/store/:vendorId" element={<StorePage />} />
        <Route path="/about" element={<AboutPage />} />
        {/* Fix: changed PrivacyPolicy to PrivacyPage to match the imported component name */}
        <Route path="/privacy" element={<PrivacyPage />} />
        <Route path="/terms" element={<TermsPage />} />

        {/* Secret Admin Route */}
        <Route path="/secret-access" element={<AdminLogin />} />

        {/* Buyer Routes */}
        <Route path="/buyer/dashboard" element={<BuyerDashboard />} />
        <Route path="/buyer/search" element={<SearchPage />} />
        <Route path="/buyer/product/:id" element={<ProductDetail />} />
        <Route path="/buyer/cart" element={<Cart />} />
        <Route path="/buyer/checkout" element={<Checkout />} />
        <Route path="/buyer/orders" element={<ProtectedRoute role="buyer"><OrdersPage /></ProtectedRoute>} />
        <Route path="/buyer/wishlist" element={<ProtectedRoute role="buyer"><WishlistPage /></ProtectedRoute>} />
        <Route path="/buyer/profile" element={<ProtectedRoute><UserProfile /></ProtectedRoute>} />

        {/* Vendor Routes */}
        <Route path="/vendor/onboarding" element={<ProtectedRoute><VendorOnboarding /></ProtectedRoute>} />
        <Route path="/vendor/dashboard" element={<ProtectedRoute role="vendor"><VendorDashboard /></ProtectedRoute>} />
        <Route path="/vendor/products" element={<ProtectedRoute role="vendor"><VendorProducts /></ProtectedRoute>} />
        <Route path="/vendor/products/new" element={<ProtectedRoute role="vendor"><AddProduct /></ProtectedRoute>} />
        <Route path="/vendor/products/:id/edit" element={<ProtectedRoute role="vendor"><EditProduct /></ProtectedRoute>} />
        <Route path="/vendor/orders" element={<ProtectedRoute role="vendor"><VendorOrders /></ProtectedRoute>} />
        <Route path="/vendor/profile" element={<ProtectedRoute role="vendor"><UserProfile /></ProtectedRoute>} />

        {/* Delivery Routes */}
        <Route path="/delivery/dashboard" element={<ProtectedRoute role="courier"><DeliveryDashboard /></ProtectedRoute>} />

        {/* Admin Routes */}
        <Route path="/admin/dashboard" element={<ProtectedRoute role="admin"><AdminDashboard /></ProtectedRoute>} />
      </Routes>
    </Layout>
  );
}

const App: React.FC = () => {
  return (
    <AppProvider>
      <Router>
         <AppContent />
      </Router>
    </AppProvider>
  );
};

