        </div>
      </div>

      {/* Categories Scroller */}
      <div className="pl-4">
        <div className="flex justify-between items-center mb-3 pr-4">
            <h3 className="font-display font-bold text-gray-900 dark:text-white text-base">Categories</h3>
        </div>
        <div className="flex gap-3 overflow-x-auto hide-scrollbar pb-2 pr-4">
