// --- Toast Notification ---
export interface ToastMessage {
    message: string;
    type: 'success' | 'error' | 'info';
}

export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [visible, setVisible] = useState(false);

    useEffect(() => {
        if (toast) {
            setVisible(true);
            const timer = setTimeout(() => {
                setVisible(false);
                setTimeout(onClose, 300); // Wait for animation
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [toast, onClose]);

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-gray-900 dark:bg-primary text-white',
        error: 'bg-red-500 text-white',
        info: 'bg-blue-500 text-white'
    };

    return (
        <div className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[100] transition-all duration-500 ease-in-out ${visible ? 'translate-y-0 opacity-100' : '-translate-y-8 opacity-0'}`}>
            <div className={`flex items-center gap-3 px-6 py-3 rounded-full shadow-2xl ${colors[toast.type]} min-w-[200px] max-w-xs`}>
                <i className={`fa-solid fa-${icons[toast.type]}`}></i>
                <span className="text-sm font-bold tracking-wide">{toast.message}</span>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { useApp } from '../context';
import { Button, Input } from '../components/UI';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { Role } from '../types';
import { LOGO_URL } from '../constants';

export const Login: React.FC = () => {
    const { login } = useApp();
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        const result = await login(email, password);

        setIsLoading(false);
        if (result.success) {
            const role = result.role;
            if (role === 'admin') navigate('/admin/dashboard');
            else if (role === 'vendor') navigate('/vendor/dashboard');
            else if (role === 'courier') navigate('/delivery/dashboard');
            else navigate('/buyer/dashboard');
        } else {
            setError(result.error || 'Login failed');
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white dark:bg-darkBg relative overflow-hidden transition-colors duration-300">
            <div className="absolute top-[-10%] right-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl opacity-50"></div>
            <div className="absolute bottom-[-10%] left-[-10%] w-80 h-80 bg-secondary/10 rounded-full blur-3xl opacity-50"></div>

            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-fade-in">
                <div className="mb-8 text-center">
                    <div className="mb-6 inline-block">
                        <img 
                          src={LOGO_URL} 
                          alt="LYNQED" 
                          className="h-48 w-48 rounded-full object-cover border-4 border-primary/20 dark:border-primary/10 mx-auto bg-white dark:bg-darkSurface shadow-2xl p-1" 
                        />
                    </div>
                    <h1 className="text-4xl font-display font-extrabold text-gray-900 dark:text-white tracking-tight">Welcome Back</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-2 font-medium">Sign in to continue to LYNQED</p>
                </div>

                {error && (
                    <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 text-red-600 dark:text-red-400 text-sm p-3 rounded-xl mb-4 flex items-center">
                        <i className="fa-solid fa-circle-exclamation mr-2"></i>
                        {error}
                    </div>
                )}

                <form onSubmit={handleLogin} className="space-y-6">
                    <Input 
                        label="Email Address" 
                        icon="envelope" 
                        type="email"
                        placeholder="you@university.edu" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        required
                    />

                    <div>
                        <Input 
                            label="Password" 
                            icon="lock" 
                            type="password"
                            placeholder="••••••••" 
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            required
                        />
                        <div className="flex justify-end -mt-3 mb-2">
                            <Link 
                                to="/forgot-password"
                                className="text-xs font-bold text-primary dark:text-primaryLight hover:text-primaryDark transition-colors"
                            >
                                Forgot Password?
                            </Link>
                        </div>
                    </div>

                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading}
                        className="shadow-xl shadow-primary/30"
                    >
                        {isLoading ? 'Signing in...' : 'Sign In'}
                    </Button>
                </form>

                <div className="mt-8 text-center text-sm text-gray-500 dark:text-gray-400">
                    Don't have an account? <Link to="/register" className="font-bold text-primary dark:text-primaryLight hover:text-primaryDark transition-colors">Create Account</Link>
                </div>
            </div>
        </div>
    );
};

export const ForgotPassword: React.FC = () => {
    const { resetPassword, showToast } = useApp();
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleReset = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        const result = await resetPassword(email);
        setIsLoading(false);

        if (result.success) {
            showToast("Reset link sent! Check your email.", "success");
            navigate('/login');
        } else {
            setError(result.error || 'Failed to send reset email.');
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white dark:bg-darkBg relative overflow-hidden transition-colors duration-300">
            <div className="absolute top-[-10%] left-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl opacity-50"></div>
            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-slide-up">
                <div className="mb-6 text-center">
                    <h1 className="text-2xl font-display font-extrabold text-gray-900 dark:text-white">Reset Password</h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-2 text-sm">Enter your email to receive reset instructions</p>
